1	import * as THREE from 'three';
2	import type { HandState } from '../../input';
3	import type { Item } from '../../items';
4	import type { InteractionFactory } from '../types';
5	
6	/**
7	 * D4 肩越しに後ろへ放る。持っている物を肩越しに頭の後ろへ持っていって離すと、見えないゴミ箱に入って消える。
8	 */
9	
10	/** 頭の中心から見て、これ以上後ろ (頭の水平な前方向と逆) にあること (m)。頭の半径が約 0.1 m なので、耳の後ろまで回したら後ろとみなす。 */
11	export const BEHIND_MIN = 0.12;
12	/** 頭からの距離の上限 (m)。肩越しに後ろへ回した手が届く範囲 (腕の長さ約 0.6～0.7 m) より少し広めに取る。遠くへ投げた物は対象にしない。 */
13	export const REACH_MAX = 0.75;
14	/** 高さの下限 (頭より何 m 低いまで許すか)。目から肩までが約 0.25～0.3 m なので、肩の高さ以上を「肩越し」とする。腰の後ろでの誤爆を避ける。 */
15	export const SHOULDER_DROP = 0.3;
16	/** 前方向の水平成分がこれより小さい (真上・真下を向いている) ときは、後ろの向きが決められないので対象にしない。 */
17	const MIN_FORWARD_HORIZONTAL = 0.1;
18	
19	/**
20	 * 「普通に後ろへ投げたいボール」を消さないための条件。
21	 * 投げるときの手は、後ろの領域を一瞬で通り抜ける。消したいときは、その領域で手を止めて、
22	 * 振動で知らせを受けてから離す。そこで、領域に入ってから離すまでに DWELL_SEC 以上かかり、
23	 * 離す瞬間の手の速さが RELEASE_SPEED_MAX 以下であることを求める。
24	 * 後ろへ向けた緩い投げ (下手) は、手が領域を通る時間が短く速いので、この 2 つで消えない。
25	 */
26	/** 領域に入ってから離すまでの最短時間 (秒)。振動の知らせ 1 回分より長く、待ち続けても苦にならない長さ。 */
27	export const DWELL_SEC = 0.35;
28	/** 離す瞬間の手の速さの上限 (m/s)。人が物をそっと置くときはおよそ 0.5 m/s 以下、投げは 2 m/s 以上になる。 */
29	export const RELEASE_SPEED_MAX = 1.2;
30	
31	/** 領域の中にいる間、知らせの振動を繰り返す間隔 (秒) と、その強さ・長さ */
32	const HINT_INTERVAL = 0.25;
33	const HINT_INTENSITY = 0.12;
34	const HINT_MS = 40;
35	/** 領域に入った瞬間と、消える瞬間の振動 */
36	const ENTER_INTENSITY = 0.3;
37	const ENTER_MS = 60;
38	const DELETE_INTENSITY = 1;
39	const DELETE_MS = 120;
40	
41	const _forward = new THREE.Vector3();
42	const _offset = new THREE.Vector3();
43	
44	/**
45	 * 位置が、頭から見て「肩越しの後ろ」の領域にあるか。
46	 * 頭の水平な前方向に対する後ろ向きの距離・頭からの距離・高さで判定する。
47	 */
48	export function isOverShoulder(
49	  headPosition: THREE.Vector3,
50	  headQuaternion: THREE.Quaternion,
51	  position: THREE.Vector3,
52	  behindMin = BEHIND_MIN,
53	): boolean {
54	  _forward.set(0, 0, -1).applyQuaternion(headQuaternion);
55	  _forward.y = 0;
56	  const length = _forward.length();
57	  if (length < MIN_FORWARD_HORIZONTAL) return false;
58	  _forward.divideScalar(length);
59	  _offset.copy(position).sub(headPosition);
60	  const behind = -(_offset.x * _forward.x + _offset.z * _forward.z);
61	  return behind >= behindMin && _offset.length() <= REACH_MAX && _offset.y >= -SHOULDER_DROP;
62	}
63	
64	/**
65	 * 素手の対策。素手は頭の後ろに回すとヘッドセットのカメラに映らず、認識が切れる (HandState.tracked が false)。
66	 * 認識が切れている間は物が動かず、つまみの終わりも手が前に戻るまで来ないので、離した位置が領域に届かない。
67	 * そこで、領域の手前 (耳の横から肩の上あたり) にある物を持ったまま認識が切れ、そのまま一定時間戻らなければ、
68	 * 後ろへ回して離したとみなして消す。後ろ向きの距離の下限を緩めるのは、認識が切れる直前の位置が手前になるため。
69	 */
70	export const NEAR_BEHIND_MIN = -0.1;
71	/** 認識が切れてから消すまでの時間 (秒)。ちらつきや一瞬の隠れを除く。 */
72	export const LOST_SEC = 0.35;
73	/** 認識が切れている間に頭の向き (水平) がこれ以上回ったら、振り向いて見えなくなっただけとみなして消さない (ラジアン、約 35 度)。 */
74	export const LOST_YAW_MAX = 0.6;
75	
76	/** 水平な向きの角度の差 (-PI..PI) の絶対値 */
77	export function yawDelta(a: number, b: number): number {
78	  const d = Math.abs(a - b) % (Math.PI * 2);
79	  return d > Math.PI ? Math.PI * 2 - d : d;
80	}
81	
82	/** 頭の水平な前方向の角度 (ラジアン)。真上・真下を向いて決まらないときは null */
83	export function headYaw(headQuaternion: THREE.Quaternion): number | null {
84	  _forward.set(0, 0, -1).applyQuaternion(headQuaternion);
85	  if (Math.hypot(_forward.x, _forward.z) < MIN_FORWARD_HORIZONTAL) return null;
86	  return Math.atan2(_forward.x, _forward.z);
87	}
88	
89	/** 認識が切れる直前に物が領域の手前にあり、切れたまま十分たち、その間に頭が大きく回っていなければ、消す。 */
90	export function shouldDeleteOnTrackingLoss(wasNear: boolean, lostSec: number, headYawChange: number): boolean {
91	  return wasNear && lostSec >= LOST_SEC && headYawChange <= LOST_YAW_MAX;
92	}
93	
94	/**
95	 * 勢いよく後ろへ振って離す削除。待たなくても、後ろへ速く振って離せば消える (後ろへ投げた物も消えてよい)。
96	 * 手の速さは、頭の水平な後ろ向きの成分で見る。体の前へ投げる動きは後ろ向きの成分が負なので、決して消えない。
97	 */
98	/** 後ろ向きの手の速さの下限 (m/s)。ゆっくり手を回すだけ (約 0.5 m/s) では消えず、軽く振れば超える値。 */
99	export const THROW_BACK_SPEED = 1.0;
100	/** 素手で、認識が切れる前の「速い後ろ向き」をどれだけ前まで有効とするか (秒)。切れる 1～2 フレーム前が最大速度になるため。 */
101	export const FAST_RECENT_SEC = 0.2;
102	/** 速い振りの後で認識が切れたとき、消すまでの待ち (秒)。1～2 フレームのちらつきを除く。 */
103	export const FAST_LOST_SEC = 0.1;
104	/** 速い振りで認識が切れる直前の、後ろ向きの距離の下限 (m)。振っている最中は耳の手前で見えなくなることがあるので、かなり緩める。 */
105	export const FAST_NEAR_BEHIND_MIN = -0.3;
106	/** 合図の音を鳴らす間隔の下限 (秒)。領域の縁での出入りで連続して鳴らさない。 */
107	const CUE_COOLDOWN = 0.8;
108	
109	/** 手の速度の、頭の水平な後ろ向きの成分 (m/s)。向きが決まらなければ 0 */
110	export function backwardSpeed(headQuaternion: THREE.Quaternion, velocity: THREE.Vector3): number {
111	  _forward.set(0, 0, -1).applyQuaternion(headQuaternion);
112	  _forward.y = 0;
113	  const length = _forward.length();
114	  if (length < MIN_FORWARD_HORIZONTAL) return 0;
115	  return -(velocity.x * _forward.x + velocity.z * _forward.z) / length;
116	}
117	
118	/** 速く後ろへ動いている手が、頭の耳の横から後ろ・肩の高さ以上・届く範囲で離したか */
119	export function isBackwardThrow(
120	  headPosition: THREE.Vector3,
121	  headQuaternion: THREE.Quaternion,
122	  position: THREE.Vector3,
123	  velocity: THREE.Vector3,
124	  behindMin = NEAR_BEHIND_MIN,
125	): boolean {
126	  return (
127	    backwardSpeed(headQuaternion, velocity) >= THROW_BACK_SPEED &&
128	    isOverShoulder(headPosition, headQuaternion, position, behindMin)
129	  );
130	}
131	
132	/** 速く後ろへ振った直後に認識が切れ、少し戻らず、頭が大きく回っていなければ、消す。 */
133	export function shouldDeleteOnFastLoss(wasFastNear: boolean, lostSec: number, headYawChange: number): boolean {
134	  return wasFastNear && lostSec >= FAST_LOST_SEC && headYawChange <= LOST_YAW_MAX;
135	}
136	
137	/** 領域に入ってから離すまでの時間と手の速さが、「わざと離した」といえるか */
138	export function isDeliberateRelease(dwellSec: number, speed: number): boolean {
139	  return dwellSec >= DWELL_SEC && speed <= RELEASE_SPEED_MAX;
140	}
141	
142	const create: InteractionFactory = (ctx) => {
143	  const head = new THREE.Vector3();
144	  const headQuaternion = new THREE.Quaternion();
145	  let hasHead = false;
146	  /** 手ごとの、領域に入った時刻と、最後に知らせの振動を出した時刻 */
147	  const zone = new Map<HandState, { since: number; lastHint: number }>();
148	  let now = 0;
149	  /** 素手: 認識が切れる直前に、持っている物が領域の手前にあったか */
150	  const nearBeforeLoss = new Map<HandState, boolean>();
151	  /** 素手: 認識が切れた時刻と、そのときの頭の向き */
152	  const lost = new Map<HandState, { since: number; yaw: number | null }>();
153	  /** 素手: 速く後ろへ振りながら領域の手前にいた最後の時刻 */
154	  const fastNearAt = new Map<HandState, number>();
155	  /** 素手: 最後に追跡できたフレームの時刻と、そのときの頭の向き (認識が切れた後に頭が回ったかの基準) */
156	  const lastTrackedAt = new Map<HandState, number>();
157	  const yawWhileTracked = new Map<HandState, number | null>();
158	  const lastCue = new Map<HandState, number>();
159	
160	  const removeWithFeedback = (hand: HandState, items: readonly Item[]): void => {
161	    // 視界の外なので、音で知らせる。音の位置は、消える物のある (頭の後ろの) 場所。
162	    const position = items[0].object.position.clone();
163	    ctx.audio.trash(position);
164	    hand.pulse(DELETE_INTENSITY, DELETE_MS);
165	    for (const item of items) ctx.items.remove(item);
166	  };
167	
168	  ctx.onItems('release', ({ hand, items }) => {
169	    const state = zone.get(hand);
170	    zone.delete(hand);
171	    if (!hasHead) return;
172	    // 持っていた手の速さ。素手とコントローラーのどちらも HandState.velocity に入る。
173	    // 領域で待ってそっと離す、または速く後ろへ振って離す、のどちらかで消す。
174	    const deliberate = state !== undefined && isDeliberateRelease(now - state.since, hand.velocity.length());
175	    // 両手で持っていた物は、もう一方の手に残るので消さない。
176	    const targets = items.filter(
177	      (item) =>
178	        ctx.items.holdersOf(item).length === 0 &&
179	        (deliberate
180	          ? isOverShoulder(head, headQuaternion, item.object.position)
181	          : isBackwardThrow(head, headQuaternion, item.object.position, hand.velocity)),
182	    );
183	    if (targets.length === 0) return;
184	
185	    removeWithFeedback(hand, targets);
186	  });
187	
188	  /** 素手の認識切れによる削除。消したら true */
189	  const handleHandLoss = (hand: HandState, held: Item[]): boolean => {
190	    const single = held.length > 0 && held.every((item) => ctx.items.holdersOf(item).length === 1);
191	    if (hand.tracked) {
192	      lost.delete(hand);
193	      lastTrackedAt.set(hand, now);
194	      yawWhileTracked.set(hand, headYaw(headQuaternion));
195	      nearBeforeLoss.set(hand, single && isOverShoulder(head, headQuaternion, held[0].object.position, NEAR_BEHIND_MIN));
196	      if (single && isBackwardThrow(head, headQuaternion, held[0].object.position, hand.velocity, FAST_NEAR_BEHIND_MIN)) {
197	        fastNearAt.set(hand, now);
198	      }
199	      return false;
200	    }
201	    const wasNear = nearBeforeLoss.get(hand) === true;
202	    const fastAt = fastNearAt.get(hand);
203	    const wasFast = fastAt !== undefined && (lastTrackedAt.get(hand) ?? -Infinity) - fastAt <= FAST_RECENT_SEC;
204	    if (!single || (!wasNear && !wasFast)) {
205	      lost.delete(hand);
206	      return false;
207	    }
208	    let state = lost.get(hand);
209	    if (!state) {
210	      // 頭の向きの基準は、認識が切れる前の最後のフレームのもの (切れてから回った分も数えるため)。
211	      state = { since: now, yaw: yawWhileTracked.get(hand) ?? null };
212	      lost.set(hand, state);
213	    }
214	    const yaw = headYaw(headQuaternion);
215	    const change = state.yaw === null || yaw === null ? 0 : yawDelta(state.yaw, yaw);
216	    const lostSec = now - state.since;
217	    if (!shouldDeleteOnTrackingLoss(wasNear, lostSec, change) && !shouldDeleteOnFastLoss(wasFast, lostSec, change)) {
218	      return false;
219	    }
220	    lost.delete(hand);
221	    nearBeforeLoss.delete(hand);
222	    fastNearAt.delete(hand);
223	    zone.delete(hand);
224	    removeWithFeedback(hand, held);
225	    return true;
226	  };
227	
228	  return {
229	    id: 'D4',
230	    label: '肩越し',
231	    category: 'delete',
232	    disable() {
233	      zone.clear();
234	      nearBeforeLoss.clear();
235	      fastNearAt.clear();
236	      lastTrackedAt.clear();
237	      yawWhileTracked.clear();
238	      lastCue.clear();
239	      lost.clear();
240	      hasHead = false;
241	    },
242	    update(frame) {
243	      now = frame.time;
244	      head.copy(frame.headPosition);
245	      headQuaternion.copy(frame.headQuaternion);
246	      hasHead = true;
247	      for (const hand of ctx.app.input.hands) {
248	        const held = ctx.items.heldBy(hand);
249	        if (hand.isHand && handleHandLoss(hand, held)) continue;
250	        // 1 本の手だけで持っている物が領域にあるときだけ、知らせる。
251	        const inZone =
252	          held.length > 0 &&
253	          held.every((item) => ctx.items.holdersOf(item).length === 1) &&
254	          isOverShoulder(head, headQuaternion, held[0].object.position);
255	        const state = zone.get(hand);
256	        if (!inZone) {
257	          zone.delete(hand);
258	          continue;
259	        }
260	        if (!state) {
261	          zone.set(hand, { since: now, lastHint: now });
262	          hand.pulse(ENTER_INTENSITY, ENTER_MS);
263	          // 素手は振動しないので、領域に着いたことを音で知らせる (入るたびに 1 回。縁での出入りは間隔を空ける)。
264	          if (now - (lastCue.get(hand) ?? -Infinity) >= CUE_COOLDOWN) {
265	            lastCue.set(hand, now);
266	            ctx.audio.zoneCue(held[0].object.position.clone());
267	          }
268	        } else if (now - state.since >= DWELL_SEC && now - state.lastHint >= HINT_INTERVAL) {
269	          // 「ここで離すと消える」状態になってから、弱い振動を繰り返す。
270	          state.lastHint = now;
271	          hand.pulse(HINT_INTENSITY, HINT_MS);
272	        }
273	      }
274	    },
275	  };
276	};
277	
278	export default create;
279

