62	    },
63	  };
64	  const removed: FakeItem[] = [];
65	  const trash: number[] = [];
66	  const cues: number[] = [];
67	  const listeners: Record<string, ((e: unknown) => void)[]> = {};
68	  let held: FakeItem[] = [item];
69	  const ctx = {
70	    app: { input: { hands: [hand] } },
71	    audio: {
72	      trash: () => trash.push(1),
73	      zoneCue: () => cues.push(1),
74	      click() {},
75	      chime() {},
76	    },
77	    items: {
78	      heldBy: () => held,
79	      holdersOf: (i: FakeItem) => (held.includes(i) ? [hand] : []),
80	      remove: (i: FakeItem) => {
81	        removed.push(i);
82	        held = held.filter((x) => x !== i);
83	      },
84	    },
85	    onItems: (event: string, l: (e: unknown) => void) => (listeners[event] ??= []).push(l),
86	  };
87	  // deno-lint-ignore no-explicit-any
88	  const interaction = create(ctx as any);
89	  const frame = (time: number) =>
90	    // deno-lint-ignore no-explicit-any
91	    interaction.update!({ time, headPosition: head, headQuaternion: facing } as any);
92	  return { item, hand, removed, trash, cues, frame, interaction, release: () => {
93	      // 本物の Items は、離した手の持ち状態を消してから通知する。
94	      const items = held;
95	      held = [];
96	      listeners.release?.forEach((l) => l({ hand, items }));
97	    },
98	  };
99	}
